  mkLRule (mkC StD (mkS [S1] [S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0] [S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 [])) 2 8.
Definition ch_iarm3_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD : list rstep := [RB (SWin 3);RB (SCycL 1 0);RB (SWin 4);RB (SCycR 1);RB (SWin 1)].
Lemma ok_iarm3_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD :
  check_arm tm false true rules iarm3_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD
            ch_iarm3_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD : LRule :=
  mkLRule (mkC StD (mkS [S1] [S0] 1 0 [S1]) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0] [S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 [])) 2 8.
Definition ch_farm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD : list rstep := [RB (SWin 3);RB (SCycL 1 0);RB (SWin 1);RB (SWinL 3);RB (SCycR 1);RB (SWin 1)].
Lemma ok_farm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD :
  check_arm tm true true rules farm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD ch_farm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0RB_0LC1RD_1LC1LA_0LA0RD (i r : nat) : LRule :=
  match i, r with
  | 0, 0 => iarm0_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD
  | 1, 0 => iarm1_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD
  | 2, 0 => iarm2_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD
  | 3, 0 => iarm3_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD
  | _, _ => iarm0_0_1RB0RB_0LC1RD_1LC1LA_0LA0RD   (* unreachable: i < 4 and r < N0i + sti *)
  end.

(** The fill arms, indexed by the WIDTH.  Both tails are known empty -- they
    are the only arms that see the end of the counter -- and the left-hand
    side is the top of the width: [1], then a run of zeros, then [1].
    That is the largest MEMBER and not the largest value ([2^k - 1] has the
    wrong parity and is not a member at all), which is why it has a fixed word
    at each end.  [fw1]/[fw2] say how the top's concrete copies of the run
    divide about the block and [fm1]/[fm2] the fill target's. *)
Definition farm_1RB0RB_0LC1RD_1LC1LA_0LA0RD (r : nat) : LRule :=
  match r with
  | 2 => farm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD
  | _ => farm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD   (* unreachable: 2 <= r < N0f + stf *)
  end.

Definition fw1_1RB0RB_0LC1RD_1LC1LA_0LA0RD (r : nat) : nat := match r with | 2 => 0 | _ => 0 end.
Definition fw2_1RB0RB_0LC1RD_1LC1LA_0LA0RD (r : nat) : nat := match r with | 2 => 0 | _ => 0 end.
Definition fm1_1RB0RB_0LC1RD_1LC1LA_0LA0RD (r : nat) : nat := match r with | 2 => 1 | _ => 0 end.
Definition fm2_1RB0RB_0LC1RD_1LC1LA_0LA0RD (r : nat) : nat := match r with | 2 => 0 | _ => 0 end.

(** One chain per state per fill arm.  [vis_of_run] turns each into a visit
