  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1] [S0] 1 0 [S1;S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0] [S0] 1 0 [S1;S0])) 4 8.
Definition ch_iarm3_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD : list rstep := [RB (SWin 1);RB (SCycR 3);RB (SWin 6);RB (SCycL 1 0);RB (SWin 1)].
Lemma ok_iarm3_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD :
  check_arm tm true false rules iarm3_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD
