  check_arm tm true true rules farm2_1RB0RB_1LC0LC_1RA1LD_0RA0LD ch_farm2_1RB0RB_1LC0LC_1RA1LD_0RA0LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0RB_1LC0LC_1RA1LD_0RA0LD (i r : nat) : LRule :=
  match i, r with
  | 0, 0 => iarm0_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD
  | 1, 0 => iarm1_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD
  | 2, 0 => iarm2_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD
  | 3, 0 => iarm3_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD
  | _, _ => iarm0_0_1RB0RB_1LC0LC_1RA1LD_0RA0LD   (* unreachable: i < 4 and r < N0i + sti *)
  end.

(** The fill arms, indexed by the WIDTH.  Both tails are known empty -- they
    are the only arms that see the end of the counter -- and the left-hand
    side is the top of the width: [1], then a run of zeros, then [1].
    That is the largest MEMBER and not the largest value ([2^k - 1] has the
    wrong parity and is not a member at all), which is why it has a fixed word
    at each end.  [fw1]/[fw2] say how the top's concrete copies of the run
    divide about the block and [fm1]/[fm2] the fill target's. *)
Definition farm_1RB0RB_1LC0LC_1RA1LD_0RA0LD (r : nat) : LRule :=
  match r with
  | 2 => farm2_1RB0RB_1LC0LC_1RA1LD_0RA0LD
  | _ => farm2_1RB0RB_1LC0LC_1RA1LD_0RA0LD   (* unreachable: 2 <= r < N0f + stf *)
  end.

Definition fw1_1RB0RB_1LC0LC_1RA1LD_0RA0LD (r : nat) : nat := match r with | 2 => 0 | _ => 0 end.
Definition fw2_1RB0RB_1LC0LC_1RA1LD_0RA0LD (r : nat) : nat := match r with | 2 => 0 | _ => 0 end.
Definition fm1_1RB0RB_1LC0LC_1RA1LD_0RA0LD (r : nat) : nat := match r with | 2 => 1 | _ => 0 end.
Definition fm2_1RB0RB_1LC0LC_1RA1LD_0RA0LD (r : nat) : nat := match r with | 2 => 0 | _ => 0 end.

(** One chain per state per fill arm.  [vis_of_run] turns each into a visit
    and [topsG_cofinal] says the tops keep coming, which is all the liveness
    needs. *)
Definition vis_1RB0RB_1LC0LC_1RA1LD_0RA0LD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 2, (StA, S0) => [SWin 1;SCycR 3;SWin 3]
  | 2, (StA, S1) => [SWin 1]
  | 2, (StB, S0) => [SWin 1;SCycR 3;SWinR 4]
  | 2, (StB, S1) => [SWin 1;SCycR 3;SWin 1]
  | 2, (StC, S0) => [SWin 1;SCycR 3;SWin 2]
  | 2, (StC, S1) => [SWin 1;SCycR 3;SWinR 5]
  | 2, (StD, S0) => []
  | 2, (StD, S1) => [SWin 1;SCycR 3;SWinR 6]
  | _, _ => []
  end.

Lemma iarm_sound_1RB0RB_1LC0LC_1RA1LD_0RA0LD : forall i r,
  i < 4 -> r < 0 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB0RB_1LC0LC_1RA1LD_0RA0LD i r).
Proof.
  intros i r Hi Hr.
