  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1] [S0] 1 0 [S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0] [S0] 1 0 [S1;S1])) 4 8.
Definition ch_farm2_1RB1LD_1RC0RC_1LA0LA_0RB0LD : list rstep := [RB (SWin 1);RB (SCycR 3);RB (SWin 3);RB (SWinR 3);RB (SCycL 1 0);RB (SWin 1)].
